def find_Product(arr, n):    
    # Initialize product for each element as 1
    product = [1]*n

    # Calculate product of all elements from left to right
    for i in range(n):
        for j in range(i):
            product[i] *= arr[j]

    # Calculate product of all elements from right to left
    for i in range(n-1,-1,-1):
        for j in range(i+1,n):
            product[i] *= arr[j]

    return product

