def find_Product(arr, n):
    # Initialize result as 1 (since 1 is the multiplicative identity)
    result = 1

    # Traverse through the array
    for i in range(n):
        # If element at current index is not repeated, multiply it with the result
        if arr[i] != arr[i+1]:
